 "callouts": [
  {
   "key": "raise",
   "label": "Raise",
   "text": "2 (JWT token exchange to the developer org + SOAP Metadata retrieve). 0 for deletions-only or manual-steps-only releases."
  },
  {
   "key": "statusPoll_retrieving",
   "label": "Page read while retrieving",
   "text": "2 per poll (token + checkRetrieveStatus)."
  },
  {
   "key": "statusPoll_retrieveDone",
   "label": "Page read when the retrieve is done",
   "text": "about 8 (token + retrieve status with zip, branch exists, create branch = 2, put file = 2 (GET sha + PUT), start pipeline) + Slack card 1-2."
  },
  {
   "key": "statusPoll_checks",
   "label": "Page read during checks",
   "text": "2-5 per poll (find pull request, find run, up to 3 result files raise/scan/validate) + Slack card edit and thread reply (about 2) only when something changed."
  },
  {
   "key": "approve",
   "label": "Approve",
   "text": "1 (start merge/deploy run) + Slack about 2."
  },
  {
   "key": "statusPoll_deploying",
   "label": "Page read while deploying",
   "text": "2-3 per poll (find run, merge result, deploy result); after deploy + 2 per flow activated (token once per org per transaction + Tooling call)."
  },
  {
   "key": "compare_start",
   "label": "Compare: start",
   "text": "2 (token + retrieve)."
  },
  {
   "key": "compare_check",
   "label": "Compare: each check",
   "text": "polled every 2 s; 2 while retrieving; then 1 listFiles + 1 raw file read per file, capped at 90 callouts and 2,000,000 characters per check (RlyCompareRun.CALL_BUDGET / TEXT_BUDGET)."
  },
  {
   "key": "orgCheck",
   "label": "Org sign-in check",
   "text": "token + REST version list + Organization query + SourceMember probe (about 4)."
  }
 ],
 "calloutNote": "Tokens are cached per org per transaction (RlyOrgSession.TOKENS). Salesforce limit: 100 callouts per transaction; the page poll interval default 30 s.",
 "storage": [
  {
   "key": "perRelease",
   "label": "Per release",
   "text": "1 RLY_Release__c + N RLY_Release_Item__c (one per component and per deletion) + about 6 RLY_Release_Event__c per hop (Raised, Pull request, Scan, Validation, Approved, Deployed; more for comments, flows, rollback) + S RLY_Manual_Step__c + S x stages RLY_Manual_Step_Run__c."
  },
  {
   "key": "perPromotion",
   "label": "Per promotion",
   "text": "1 RLY_Release__c + copies of the carried releases' items (RlyCarried) + about 5 events (+ step runs in the next stage)."
  },
  {
   "key": "perBackPromoteSync",
   "label": "Per back promote sync",
   "text": "1 RLY_Release__c + a few events per back promote org."
  },
  {
   "key": "fixed",
   "label": "Fixed",
   "text": "RLY_Org__c one per org, RLY_Git_Connection__c 1, RLY_Notification__c 1."
  },
  {
   "key": "example",
   "label": "Example",
   "text": "10 components, 2 manual steps, route developer org -> stage 1 -> stage 2 -> production (3 hops: 1 release + 2 promotions): releases 3, items 10 + 20 copies = 30, events about 18, steps 2, runs 6 -> about 59 records, about 118 KB."
  },
  {
   "key": "perRecordEstimate",
   "label": "Per record",
   "text": "about 2 KB (Salesforce counts most custom object records as 2 KB)"
  }
 ],
